import{_ as t,o as s,c as o,ah as a}from"./chunks/framework.ChH6X6u6.js";const u=JSON.parse('{"title":"Year-end decisions","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"en/guide/admin/decisions-fin-annee.md","filePath":"src/en/guide/admin/decisions-fin-annee.md"}'),n={name:"en/guide/admin/decisions-fin-annee.md"};function r(i,e,d,l,c,h){return s(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="year-end-decisions" tabindex="-1">Year-end decisions <a class="header-anchor" href="#year-end-decisions" aria-label="Permalink to &quot;Year-end decisions&quot;">​</a></h1><p>At the end of the year, each student moves up, repeats the year or leaves the school. ERA proposes a decision for each student from their results; <strong>the administrator alone</strong> accepts or changes it. These decisions are then used to <a href="/era-guide/en/guide/admin/reinscriptions.html">re-enroll students</a> into the next year.</p><h2 id="before-you-start" tabindex="-1">Before you start <a class="header-anchor" href="#before-you-start" aria-label="Permalink to &quot;Before you start&quot;">​</a></h2><ul><li><strong>Levels</strong>: each class needs a level, and each level its next level (see <a href="/era-guide/en/guide/admin/structure-etablissement.html#levels">Levels</a>). Tick <strong>Exam year</strong> on levels ending in a national exam, and <strong>Last level of the school</strong> on the highest one.</li><li><strong>Each department&#39;s pass mark</strong>: in <strong>School setup → Departments</strong>, field <strong>Pass mark</strong> (10 by default).</li><li><strong>The last period closed</strong>: decisions open once the year&#39;s last period is closed (see <a href="/era-guide/en/guide/admin/structure-etablissement.html#closing-a-year-or-a-term">Closing a year or a term</a>), when averages can no longer change. No need to wait for the end of the year: June class councils can meet as soon as the last term is closed. Before that, the page already shows the proposals, read-only.</li></ul><h2 id="deciding-for-a-class" tabindex="-1">Deciding for a class <a class="header-anchor" href="#deciding-for-a-class" aria-label="Permalink to &quot;Deciding for a class&quot;">​</a></h2><ol><li>Open <strong>Students &amp; admissions → Year-end decisions</strong>.</li><li>Choose the <strong>Academic year</strong>, then the <strong>Class</strong>. The class list shows progress, e.g. &quot;12/35 decided&quot;.</li><li>For each student, the page shows their <strong>Annual average</strong> (in orange below the pass mark), ERA&#39;s <strong>Proposal</strong> with its reason, and the recorded <strong>Decision</strong>.</li></ol><p>Three ways to record decisions:</p><ul><li><strong>Accept proposals (n)</strong>: records at once the proposal of every student in the class who has no decision yet. Students already decided are never changed; those without a proposal remain to decide one by one.</li><li><strong>Accept proposal</strong>, on a student&#39;s row.</li><li><strong>Decide</strong> (or <strong>Edit</strong>): choose the decision yourself and optionally add a <strong>Note</strong>, e.g. &quot;Moved up by the class council&quot;.</li></ul><p><strong>Cancel decision</strong> puts the student back to &quot;to decide&quot;.</p><p>Once the student is re-enrolled into the next year, their decision can no longer be changed or cancelled: the row shows &quot;Re-enrolled in …&quot;.</p><p>Each decision keeps the annual average it was taken on, its author and its date.</p><h2 id="how-era-proposes" tabindex="-1">How ERA proposes <a class="header-anchor" href="#how-era-proposes" aria-label="Permalink to &quot;How ERA proposes&quot;">​</a></h2><p>In this order:</p><table tabindex="0"><thead><tr><th>Situation</th><th>Proposal</th></tr></thead><tbody><tr><td>Permanently excluded by a discipline council this year</td><td>Leaves the school</td></tr><tr><td>Class of a level marked <strong>Exam year</strong></td><td>None: decide from the exam results</td></tr><tr><td>Department assessed without numeric grades (nursery, preschool)</td><td>Moves up</td></tr><tr><td>No grades this year</td><td>None: to decide</td></tr><tr><td>Annual average at or above the pass mark</td><td>Moves up</td></tr><tr><td>Annual average below the pass mark</td><td>Repeats the year</td></tr></tbody></table><p>An average exactly equal to the pass mark is a pass.</p><p>On the school&#39;s last level, &quot;Moves up&quot; reads <strong>Passed · leaves the school</strong>: the student succeeded and leaves.</p><div class="tip custom-block"><p class="custom-block-title">A proposal is only a starting point</p><p>A student at 9.50 can be moved up by the class council, a student who passed may go to another school: just change their decision.</p></div>',17)])])}const g=t(n,[["render",r]]);export{u as __pageData,g as default};
